C=[]
def add(id,title,who,status,what,req,limits,valid,example,sources): C.append(dict(id=id,title=title,who=who,status=status,what=what,requirements=req,limits=limits,validity=valid,example=example,sources=sources,verified='2026-11-14'))
add('intereses','Intereses hipotecarios · artículo 55 bis','Persona natural','Vigente','Permite rebajar intereses de la base imponible anual; no es un descuento del precio de la vivienda.','Crédito con garantía hipotecaria destinado a adquirir o construir viviendas, o a refinanciar esos créditos; intereses efectivamente pagados y acreditados.','Tope: menor entre intereses pagados y 8 UTA. La rebaja se reduce en el tramo de 90 a 150 UTA y no procede sobre 150 UTA. No incluye amortización de capital ni el dividendo completo.','Regla vigente al 14/11/2026; evaluación anual.','Una persona con crédito para vivienda revisa su certificado anual y su renta imponible antes de aplicar la deducción. No se estima aquí su ahorro.',['lir','intereses'])
add('dfl-persona','DFL2 · rentas de las dos primeras viviendas','Persona natural','Vigente','Las rentas de viviendas económicas que cumplen las condiciones pueden quedar fuera de la tributación ordinaria de renta.','Calidad DFL2 acreditada, destino habitacional y superficie edificada de hasta 140 m². Se consideran las dos viviendas DFL2 de adquisición más antigua, incluidas participaciones de dominio.','El límite no se elige según cuál produzca más arriendo. Una sociedad no recibe esta franquicia de persona natural. La exención de renta no libera automáticamente la futura venta.','Regla actual de máximo dos viviendas. El régimen opcional de 2027 es distinto.','Si tienes dos viviendas DFL2 y una es tu residencia, la tercera no pasa a estar exenta porque la primera no se arriende.',['dfl','catastro'])
add('arriendo','Ingresos por arriendo','Personas y empresas','Vigente','El ingreso por arriendo debe evaluarse para la declaración anual, salvo franquicia aplicable. Renta e IVA son impuestos distintos.','Identificar titular, destino, contrato, calidad DFL2 y régimen tributario.','Un arriendo sin amoblar puede estar exento de IVA y aun así tributar por renta. El arriendo amoblado o con instalaciones puede quedar afecto a IVA; revisar exenciones, incluida la DFL2 cuando corresponda.','Normas vigentes; el 5% de 2027 requiere opción y condiciones propias.','Un departamento no DFL2 arrendado sin muebles no se vuelve libre de impuesto a la renta por no generar IVA.',['lir','iva','dfl'])
add('venta','Venta · eventual límite de 8.000 UF','Persona natural','Condicionado','Ciertos mayores valores de inmuebles situados en Chile pueden ser ingreso no renta hasta un límite acumulado de 8.000 UF.','Aplicación del art. 17 N°8 b): persona natural, inmueble fuera de su empresa individual, comprador no relacionado y plazos legales. En general más de un año; cuatro años en casos especiales de subdivisión o edificios por pisos/departamentos.','No son 8.000 UF por propiedad ni por año. Revisar ganancias anteriores, costo tributario, mejoras acreditadas y fecha de adquisición. Los inmuebles adquiridos antes del 01/01/2004 tienen reglas transitorias que exigen revisión separada.','Régimen vigente, sujeto a historia del contribuyente y del inmueble.','Antes de vender, reunir escrituras, mejoras y ventas anteriores permite determinar si queda saldo del límite; ser DFL2 no basta.',['lir','venta'])
add('contribuciones','Contribuciones · exenciones y rebajas','Personas y empresas, según franquicia','Condicionado','El impuesto territorial depende del avalúo fiscal, destino y exenciones registradas, no únicamente del precio de compra.','Consultar certificado de avalúo y catastro SII. El DFL2 puede tener una exención del 50% por 20, 15 o 10 años según superficie: hasta 70 m², más de 70 hasta 100 m², y más de 100 hasta 140 m².','Los plazos corren desde la recepción, no desde cada reventa. El terreno no goza de la exención DFL2. No sumar automáticamente exenciones ni usar un avalúo exento antiguo como valor vigente.','Beneficios actuales según rol y plazo remanente. Ver cambio especial para mayores de 65 años desde 2027.','En una compra usada, pide el detalle de contribuciones: el beneficio temporal puede estar próximo a terminar.',['contribuciones','catastro'])
add('credito21631','Ley 21.631 · beneficio de compras anteriores','Persona natural','Ingreso cerrado','Crédito extraordinario anual de hasta 16 UTM para operaciones históricas que cumplieron la ley; limitado también por dividendos efectivamente pagados.','Vivienda habitacional nueva, crédito hipotecario bancario o financiero y requisitos de recepción/promesa. Inscripción antes del 01/10/2024; para beneficiarios de subsidio MINVU, la ley contempla la escritura en ese plazo.','No disponible para una compra que se realiza ahora en 2026. Solo una vivienda por beneficiario; revisar todas las condiciones y compatibilidades del artículo único.','Años tributarios 2024 a 2029 para beneficiarios habilitados; pagos hasta año comercial 2028. Ventana de adquisición cerrada.','Quien compró válidamente en 2024 puede revisar su crédito anual; quien compra en noviembre de 2026 no puede invocarlo por esa nueva compra.',['credito'])
add('activo','La compra se registra como inversión','Empresa','Regla general','Distinguir activo para uso propio, inmueble para renta o existencias para venta. El reconocimiento contable y la deducción tributaria no son equivalentes.','Documentar costo de adquisición y destino real; separar terreno y construcción; conciliar contabilidad con el régimen fiscal.','Comprar no convierte el precio total en gasto deducible inmediato. El suelo no se deprecia. Las existencias destinadas a vender se tratan mediante costo, no depreciación del activo fijo.','Reglas de costo y activo fijo vigentes.','Una empresa que compra una oficina registra la inversión y evalúa la construcción depreciable; no descuenta automáticamente todo el precio.',['lir','depreciacion'])
add('depreciacion','Depreciación de la construcción','Empresa','Condicionado','Puede reconocerse el desgaste de una construcción del activo inmovilizado utilizada en el negocio.','Aplicar vida útil y método permitido, con costo separado y uso empresarial acreditado. Art. 31 N°5 y 5 bis, o reglas especiales del régimen.','No depreciar el terreno. Régimen general y Pro Pyme difieren: este último puede contemplar depreciación instantánea de activos físicos depreciables, si cumple requisitos; no es una rebaja universal de la compra.','Según régimen y ejercicio. No reutilizar regímenes transitorios vencidos.','Una bodega utilizada en el giro requiere separar el suelo de la edificación antes de evaluar la depreciación.',['lir','depreciacion'])
add('gastos','Intereses y gastos aceptados','Empresa','Condicionado','Intereses, gastos financieros y otros desembolsos pueden tener tratamiento tributario cuando cumplen los requisitos legales.','Vinculación con el interés, desarrollo o mantenimiento del giro; acreditación fehaciente, período correcto y requisitos del art. 31. Revisar si corresponde costo o gasto.','La amortización del préstamo no equivale a interés deducible. Gastos personales, sin respaldo o asociados a rentas exentas pueden requerir rechazo o tratamiento especial.','Reglas vigentes, con diferencias por régimen y operación.','Intereses de un préstamo para una oficina del giro deben respaldarse y clasificarse; el mismo crédito para uso particular de un socio exige otro análisis.',['lir','gastos'])
add('iva','IVA y crédito fiscal','Empresa o contribuyente de IVA','Condicionado','El IVA soportado puede utilizarse como crédito fiscal solo si la ley lo permite. Crédito fiscal no significa devolución automática en dinero.','Factura válida, relación con actividad y destino a operaciones gravadas. Usos mixtos pueden exigir proporcionalidad. La devolución del art. 27 bis tiene requisitos propios.','No basta comprar a nombre de una sociedad. Operaciones exentas o no gravadas pueden impedir el crédito. Si la compra está exenta de IVA, no hay IVA de esa compra que recuperar.','Normas vigentes. La Ley 21.850 agrega una exención de venta desde diciembre de 2026.','Una sociedad que arrienda sin amoblar no debe presupuestar recuperar IVA sin revisar el destino y las exenciones.',['iva'])
add('empresa-venta','Arriendo, venta y régimen de la empresa','Empresa','Regla general','Arriendos y resultado de la venta se incorporan al tratamiento tributario de la empresa según su régimen, costo y naturaleza del activo.','Revisar art. 14 A, Pro Pyme general o transparente, requisitos de acceso, giro y renta percibida/devengada. En la venta revisar además habitualidad y hechos gravados con IVA.','Las 8.000 UF personales no se trasladan a la sociedad. La salida de fondos a socios tiene su propia tributación. No toda sociedad de arriendo reúne requisitos Pro Pyme.','Régimen vigente en cada ejercicio; desde 2027 revisar el régimen especial DFL2 si procede.','Vender un inmueble por la sociedad y luego distribuir el dinero requiere analizar ambas etapas; el saldo en caja no equivale a utilidad libre de impuestos.',['lir','iva'])
add('uso-personal','Uso personal de un inmueble de la sociedad','Empresa y sus propietarios','Riesgo','Que la sociedad sea propietaria no transforma el uso privado en actividad del negocio.','Documentar uso efectivo, pagos, contratos, beneficiarios y vínculo con el giro.','Puede haber gastos rechazados y tributación por beneficio a socios o relacionados conforme al art. 21. También puede afectar crédito fiscal, deducciones y financiamiento.','Revisión necesaria antes de comprar o cambiar el uso.','Una casa de la sociedad usada gratuitamente por el socio y su familia requiere análisis específico; no debe modelarse como gasto empresarial ordinario.',['lir','gastos'])
add('iva2026','Exención transitoria de IVA · vivienda nueva','Personas y empresas, según operación','Desde 01/12/2026','Opción de eximir ventas que normalmente estarían afectas a IVA. No es un descuento universal del 19% del precio final.','Primera enajenación de vivienda nueva destinada a habitación; recepción definitiva acreditada con fecha anterior al 17/10/2026. Escritura dentro del período o promesa por escritura pública/instrumento protocolizado en ese período y compraventa posterior.','Vigencia de un año desde 01/12/2026. Bodegas y estacionamientos solo bajo las condiciones de mismo acto y recepción del art. cuarto transitorio. No basta que el proyecto prometa entrega futura; no presume recepción.','Ley publicada el 17/10/2026. Aplicación futura al corte 14/11/2026; ventana ordinaria hasta 30/11/2027.','Una vivienda con recepción de 2027 no satisface el requisito de recepción anterior a la publicación de esta ley.',['reforma','resolucion'])
add('restitucion','Restitución de IVA en operaciones anteriores','Comprador y vendedor elegibles','Procedimiento desde 01/12/2026','El vendedor restituye el IVA al comprador y solicita al SII la devolución del impuesto restituido. No es una solicitud directa universal del comprador.','Escritura en el período entre ingreso del mensaje presidencial y el 01/12/2026, IVA pagado y restantes requisitos legales; mención expresa de la opción en escritura y acreditación de la restitución.','Aplicar Resolución 146: F3298 por vendedor y operación; F3299 del comprador para acreditar recepción. F3299 previo a la solicitud; F29 presentado e impuesto enterado. Si hubo CEEC, revisar el ajuste del monto según la resolución. Plazo de tres años desde 01/12/2026. No prometer pago ni monto.','Resolución definitiva emitida el 23/10/2026; procedimiento habilitado desde diciembre. Circular general aún en consulta al corte.','Para una compra anterior, primero se verifica elegibilidad con el vendedor; no se resta IVA del precio ni se promete devolución por cuenta propia.',['reforma','resolucion'])
add('dfl2027','DFL2 · opción de impuesto único del 5%','Personas y empresas con requisitos distintos','Desde 01/01/2027','Impuesto opcional sobre rentas brutas contractuales de viviendas económicas de hasta 90 m²; sin deducción de gastos.','Persona natural: desde la tercera vivienda, no asignada a empresa individual, arriendo a no relacionados. Persona jurídica: arriendo a no relacionados, giro exclusivo y opción al inicio de actividades según art. 24 ter; empresario individual, desde la tercera.','No es exención de renta. Para art. 24 ter: no admite giro activo diverso; salida sin reingreso; declaración anual, PPM y sin devolución del art. 27 bis. La venta se analiza por separado, no se grava automáticamente al 5%.','Régimen permanente desde 01/01/2027. Extensión transitoria a DFL2 nuevas hasta 140 m² compradas a no relacionados dentro de 12 meses desde 17/10/2026; esa ventana no limita el régimen a un solo año.','Un arrendador con tercera vivienda DFL2 de 80 m² puede evaluar la opción en 2027. Una sociedad con otro giro activo no debe asumir que puede incorporarse.',['reforma','calendario'])
add('mayores2027','Vivienda principal de personas de 65 años o más','Persona natural','Desde 01/01/2027','Nueva exención del 100% de contribuciones para vivienda principal que cumpla las condiciones legales.','Declarar la vivienda principal ante el SII y cumplir residencia habitual, edad y condiciones de propiedad; revisar copropiedad, deudas y derechos de aseo.','Solo vivienda principal y dependencias que califican; no toda la cartera. Existen reglas de uso mixto, relacionados y pérdida del beneficio. No aplica por comprar mediante una sociedad.','Desde 01/01/2027. El SII informa plazo hasta 31/12/2026 para acogerse desde enero de 2027.','Una persona de 67 años con dos inmuebles revisa cuál es su residencia habitual y realiza el trámite; no declara ambos como vivienda principal.',['reforma','mayores'])
